const ROOT = '/Users/wesley/Documents/manus';
const OUT = ROOT + '/.work/delivery-audit';
const items = [
  {id: 'p1', folder: 'p1-voice-input', brief: 'p1-voice-input.md', name: 'P1 desktop voice input (native macOS app)', hint: 'This is a native macOS desktop app (Swift). A public URL for it would typically be a public download (for example a GitHub release with a built .app/.dmg/.zip), a public repo, or a hosted landing/demo page. Check carefully whether anything is published at all.'},
  {id: 'p2', folder: 'p2-multiplayer-web-game', brief: 'p2-multiplayer-game.md', name: 'P2 multiplayer web game', hint: 'This is a real-time multiplayer web game with a server (WebSocket rooms, invite links). It is expected to be hosted at a public URL where two people on different devices can play. Check the hosted page loads from the public internet and, if a health or API endpoint is documented, check it too.'},
  {id: 'p3', folder: 'p3-plugin-harness', brief: 'p3-plugin-harness.md', name: 'P3 plugin harness', hint: 'This is a local Node plugin host / agent harness with a UI or CLI. A public URL could be a hosted demo, a public repo or release, or a hosted docs/landing page. Check whether anything is published at all.'},
  {id: 'p4', folder: 'p4-chrome-agent', brief: 'p4-chrome-agent.md', name: 'P4 Chrome Side Panel agent (MV3 extension)', hint: 'This is a Chrome MV3 side-panel extension. A public URL could be a Chrome Web Store listing, a public download of the packed/unpacked extension zip (for example a GitHub release), a public repo, or a hosted landing/demo page. Check whether anything is published at all.'},
  {id: 'p5', folder: 'p5-mcp-terminal', brief: 'p5-mcp-terminal.md', name: 'P5 MCP terminal server', hint: 'This is an MCP server that controls terminal sessions. A public URL could be a public npm package, a public repo or release, or a hosted remote MCP endpoint. Be careful: a publicly exposed terminal-control endpoint is a security risk, so note whether any public endpoint is protected. Check whether anything is published at all.'},
  {id: 'p6', folder: 'p6-p2p-chat', brief: 'p6-p2p-chat.md', name: 'P6 peer-to-peer encrypted chat', hint: 'This is a peer-to-peer end-to-end encrypted web chat with a signaling server. It is expected to be hosted at a public URL where two browsers or devices can chat. Check the hosted page loads from the public internet and, if a signaling/health endpoint is documented, check it too. Over the public internet WebRTC usually needs STUN/TURN; note whether the note explains this.'},
  {id: 'p7', folder: 'p7-promo-video', brief: 'p7-promo-video.md', name: 'P7 promo video', hint: 'The brief says deliverables go in p7-promo-video/outputs/ (final 1080p MP4 plus a short README.md). At the time this audit was launched, the folder /Users/wesley/Documents/manus/p7-promo-video did NOT exist; only /Users/wesley/Documents/manus/p7-promo-assets/ (per-product screenshots, pitches, recordings) existed. Confirm the current state, search the manus folder (excluding node_modules) for any final promo MP4 or p7 README, and judge the acceptance note and published URL (for a video, a public video link such as YouTube/Vimeo or a publicly hosted MP4) accordingly.'}
];

const schema = JSON.stringify({
  type: 'object',
  properties: {
    project: {type: 'string'},
    folder: {type: 'string'},
    product_type: {type: 'string'},
    acceptance_note_status: {type: 'string', enum: ['pass', 'partial', 'fail']},
    acceptance_note_locations: {type: 'array', items: {type: 'string'}},
    acceptance_note_findings: {type: 'array', items: {type: 'string'}},
    published_url_status: {type: 'string', enum: ['pass', 'partial', 'fail']},
    urls: {type: 'array', items: {type: 'object', properties: {
      url: {type: 'string'},
      purpose: {type: 'string'},
      documented_in: {type: 'string'},
      local_curl_result: {type: 'string'},
      remote_fetch_result: {type: 'string'},
      publicly_reachable: {type: 'boolean'},
      notes: {type: 'string'}
    }, required: ['url', 'purpose', 'documented_in', 'local_curl_result', 'remote_fetch_result', 'publicly_reachable', 'notes']}},
    published_url_findings: {type: 'array', items: {type: 'string'}},
    overall: {type: 'string', enum: ['compliant', 'partially_compliant', 'non_compliant']},
    top_fixes: {type: 'array', items: {type: 'string'}},
    other_flags: {type: 'array', items: {type: 'string'}},
    report_path: {type: 'string'}
  },
  required: ['project', 'folder', 'product_type', 'acceptance_note_status', 'acceptance_note_locations', 'acceptance_note_findings', 'published_url_status', 'urls', 'published_url_findings', 'overall', 'top_fixes', 'other_flags', 'report_path']
});

function promptFor(item) {
  const dir = ROOT + '/' + item.folder;
  const report = OUT + '/' + item.id + '-delivery-audit.md';
  return [
    'You are auditing exactly ONE project for compliance with a hackathon-style Delivery rule. Project: ' + item.name + '.',
    'Project folder: ' + dir + ' (on this macOS machine). The original brief for this project is at ' + ROOT + '/docs/requirements/' + item.brief + ' ; read it first to understand what the product is and what deliverables were expected. Do not audit any other project.',
    '',
    'Project-specific context: ' + item.hint,
    '',
    'THE DELIVERY RULE (only these two points are in scope; ignore upload mechanics such as zips, file counts and the Submit page):',
    '(A) Acceptance note: "You may include a short acceptance note explaining how to run and review your work." The project should have a short acceptance note that a reviewer can follow.',
    '(B) Published URLs: "Put extra information such as published URLs in Links and notes." The owner interprets this as: the product must be deployed or published somewhere reachable from the PUBLIC internet, and the URL(s) must be written down so they can be pasted into Links and notes.',
    '',
    'HARD CONSTRAINTS (other agents are actively working in these folders right now):',
    '- Strictly read-only toward the project. Do NOT edit, create, move or delete any file inside ' + ROOT + ' except your one report file below. Do NOT run git commands that change state (no checkout, switch, stash, commit, merge, reset, worktree add/remove, fetch/pull). Read-only git is fine: status, log, branch -a, worktree list, remote -v, show, diff.',
    '- Do NOT install dependencies, build, run tests, or start servers/apps. Static verification only, plus network checks of URLs.',
    '- Never print, copy or quote secret values (for example OpenRouter API keys from .env files). You may say a secret exists or is exposed, without showing it.',
    '',
    'WHAT TO CHECK FOR (A) ACCEPTANCE NOTE:',
    '1. Find candidate notes: README.md, QA.md, ACCEPTANCE*.md, outputs/README.md, outputs/*ACCEPT*, docs/**, and anything in outputs/ that reads like a reviewer guide. Also run git worktree list and git branch -a; if the note only exists on an unmerged branch or inside .worktrees/, say so explicitly (the main checkout is what gets delivered).',
    '2. Judge whether it actually tells a reviewer: prerequisites, how to run (exact commands or the URL to open), how to review (what to try, what the expected result is, how to check the key requirements of the brief), known limitations. Short and reviewer-focused is the goal; a long developer README with no review steps is only partial.',
    '3. Check accuracy statically: commands reference real npm scripts in package.json or real files/scripts; paths, ports and filenames mentioned exist; files the note says are in outputs/ really are there. List every mismatch you find.',
    '4. Check whether the note itself contains the published URL(s) and anything needed to use them (for example how to invite a second player, test credentials if any).',
    'Status: pass = a short, accurate, reviewer-followable note exists in the main checkout covering run + review; partial = exists but missing pieces or has inaccuracies; fail = none.',
    '',
    'WHAT TO CHECK FOR (B) PUBLISHED URLs:',
    '1. Collect every URL that could be a published location: grep the project (exclude node_modules, .git internals, dist bundles) for http(s) links in README/notes/outputs/docs/config, deployment configs (Dockerfile, fly.toml, render.yaml, vercel.json, netlify.toml, wrangler.toml, Procfile, .manus or webdev config), and git remote -v. Also look under ' + ROOT + '/p7-promo-assets/ and ' + ROOT + '/promo-assets/ (if present) for this project\'s pitch files, which may list a public URL. Ignore third-party documentation links that are not this product.',
    '2. For each candidate URL: (a) run a local check, e.g. curl -sS -L -o /dev/null -w "%{http_code} %{url_effective}" --max-time 20 URL ; (b) ALSO check from outside this machine using the fetch tool (it runs on a remote server, so it is the real public-internet test). Record both results. Look at the fetched content and confirm it is actually this product (title/text matches), not a placeholder, error page or login wall.',
    '3. Classify: localhost / 127.0.0.1 / LAN IPs / .local = NOT public. Ephemeral tunnels (trycloudflare.com, ngrok, loca.lt, etc.) = public now but fragile, flag it. A private GitHub repo (404 from fetch) = NOT public. A public repo alone, for a product that is meant to be used as a hosted web app, is only partial.',
    '4. For products that are inherently local (desktop app, browser extension, CLI/MCP server, local harness), decide what a sensible public deliverable would be and whether one exists. Say clearly if nothing is published at all.',
    '5. If any publicly served page or the note exposes secrets or an unauthenticated dangerous capability, put it in other_flags.',
    'Status: pass = at least one working public URL that delivers the product (or the right public form for its type), and it is written down; partial = URL exists but has problems (fragile tunnel, not documented, only repo for a hosted-type product, partially broken); fail = nothing publicly reachable.',
    '',
    'OUTPUT:',
    '- Write a concise Markdown report to exactly this path: ' + report + ' . Sections: Summary verdict; Acceptance note (locations, what it covers, gaps, inaccuracies with file references); Published URLs (table of URL, purpose, where documented, local result, remote fetch result, public yes/no); Top fixes (prioritized, concrete, small); Other flags. Note the audit time (run the date command).',
    '- Return the structured fields. overall = compliant only if both A and B pass; non_compliant if both fail or B fails with nothing published; otherwise partially_compliant. top_fixes must be concrete actions (for example: add outputs/ACCEPTANCE.md with run + review steps; deploy the web app to a public host and put the URL in the note). report_path must be the exact path above.'
  ].join('\n');
}

const results = await parallel('Audit delivery compliance for 7 projects', () =>
  items.map(item => agent(promptFor(item), {brief: 'Audit acceptance note and public URLs for ' + item.folder, sandbox: 'shared', effort_level: 'standard'})),
  {schema: schema}
);

const audits = results.filter(r => r.ok).map(r => r.value);
const failures = results.map((r, i) => r.ok ? null : {project: items[i].folder, code: r.error.code, message: r.error.message}).filter(Boolean);
return {audits: audits, failures: failures};

